use vstd::prelude::*;
use vstd::string::*;

verus! {

spec fn is_lowercase_char(c: char) -> bool {
    'a' <= c && c <= 'z'
}

spec fn all_lowercase(v: Seq<char>) -> bool {
    v.len() > 0 && forall|i: int| 0 <= i < v.len() ==> is_lowercase_char(v[i])
}

fn check_all_lowercase(v: &Vec<char>) -> (b: bool)
    ensures
        b == all_lowercase(v@),
{
    let mut i: usize = 0;
    let mut all_lower = true;
    
    while i < v.len()
        invariant
            0 <= i <= v.len(),
            all_lower == all_lowercase(v@.subrange(0, i as int)),
        decreases v.len() - i,
    {
        if !('a' <= v[i] && v[i] <= 'z') {
            all_lower = false;
        }
        i = i + 1;
    }
    
    // Check if vector is non-empty
    if v.len() == 0 {
        false
    } else {
        all_lower
    }
}

fn solve(input: Vec<char>) -> (output: Vec<char>)
    ensures
        output@.len() == 1,
        all_lowercase(input@) ==> output@[0] == 'a',
        !all_lowercase(input@) ==> output@[0] == 'A',
{
    let is_all_lowercase = check_all_lowercase(&input);
    
    let result_char = if is_all_lowercase {
        'a'
    } else {
        'A'
    };
    
    let mut output_vec = Vec::new();
    output_vec.push(result_char);
    
    output_vec
}

}